def test_apply_discount(self):
    self.assertEqual(apply_discount([100], 10), 96.3)

def test_apply_discount_multiple(self):
    # 100 + 200 = 300, 25% off -> 225, with 7% tax -> 240.75
    self.assertEqual(apply_discount([100, 200], 25), 240.75)

def test_apply_discount_zero(self):
    self.assertEqual(apply_discount([100], 0), calc_total([100]))
